<?php require_once "includes/header.php"; $codigo=trim($_GET['codigo']??$_POST['codigo']??''); $denuncia=null; $mensagens=[]; if($codigo){$stmt=$pdo->prepare("SELECT * FROM denuncias WHERE codigo=?");$stmt->execute([$codigo]);$denuncia=$stmt->fetch(PDO::FETCH_ASSOC); if($denuncia){$stmt=$pdo->prepare("SELECT * FROM denuncias_mensagens WHERE denuncia_id=? ORDER BY criado_em ASC");$stmt->execute([$denuncia['id']]);$mensagens=$stmt->fetchAll(PDO::FETCH_ASSOC);}} function estadoDen($e){return ['recebida'=>'Recebida','em_analise'=>'Em análise','info_solicitada'=>'Informação solicitada','encaminhada'=>'Encaminhada','concluida'=>'Concluída','arquivada'=>'Arquivada'][$e]??$e;} ?>
<style>.ac-page{background:linear-gradient(180deg,#f8fafc,#fff);padding:80px 0}.ac-card{max-width:900px;margin:auto;background:white;border:1px solid #e5e7eb;border-radius:30px;padding:30px;box-shadow:0 20px 55px rgba(0,0,0,.10)}.ac-card h1{color:#11151B;font-size:38px}.ac-form{display:flex;gap:10px;flex-wrap:wrap}.ac-form input{flex:1;min-width:260px;border:1px solid #dbe4ee;background:#f8fafc;border-radius:16px;padding:0 15px;min-height:54px;font-weight:800}.ac-btn{border:0;background:#242A30;color:white;border-radius:16px;padding:14px 18px;font-weight:900;cursor:pointer}.ac-status{background:#eef2ff;color:#242A30;border-radius:18px;padding:18px;margin-top:22px;font-weight:900}.ac-msg{background:#f8fafc;border:1px solid #e5e7eb;border-radius:18px;padding:16px;margin-top:12px}.ac-empty{background:#fee2e2;color:#991b1b;border-radius:18px;padding:16px;margin-top:20px;font-weight:900}</style>
<main class="ac-page"><div class="container"><div class="ac-card"><h1>Acompanhar Denúncia</h1><p>Introduza o código recebido no momento da submissão.</p><form method="POST" class="ac-form"><input type="text" name="codigo" placeholder="Ex: GR-2026-ABCDEFGH" value="<?= htmlspecialchars($codigo) ?>" required><button class="ac-btn">Consultar</button></form><?php if($codigo&&!$denuncia): ?><div class="ac-empty">Não foi encontrada nenhuma denúncia com esse código.</div><?php endif; ?><?php if($denuncia): ?><div class="ac-status">Estado atual: <?= htmlspecialchars(estadoDen($denuncia['estado'])) ?></div><h2><?= htmlspecialchars($denuncia['assunto']) ?></h2><p><strong>Categoria:</strong> <?= htmlspecialchars($denuncia['categoria']) ?></p><p><strong>Submetida em:</strong> <?= date('d/m/Y H:i', strtotime($denuncia['criado_em'])) ?></p><h3>Mensagens</h3><?php foreach($mensagens as $m): ?><div class="ac-msg"><strong><?= $m['origem']==='admin'?'Entidade':'Denunciante' ?></strong><br><?= nl2br(htmlspecialchars($m['mensagem'])) ?><br><small><?= date('d/m/Y H:i', strtotime($m['criado_em'])) ?></small></div><?php endforeach; ?><?php if(empty($mensagens)): ?><p>Ainda não existem mensagens associadas.</p><?php endif; ?><?php endif; ?></div></div></main>
